/**
 * Types for the curated 3D asset catalogue (public/game3d/models/manifest.json, docs/WORLD_3D_SPEC.md).
 * The manifest is generated by scripts/3d/curate.mjs; edit the SELECTION table there, not the JSON.
 */

export const MODEL_KINDS = [
  "terrain",
  "building",
  "nature",
  "prop",
  "character",
  "bridge",
] as const;

export type ModelKind = (typeof MODEL_KINDS)[number];

export const MANIFEST_URL = "/game3d/models/manifest.json";
export const MODELS_BASE_URL = "/game3d/models/";

export interface ModelEntry {
  file: string;
  /** Short content hash of the file (scripts/3d/hash-models.mjs); versions the URL so it can be cached forever. */
  hash?: string;
  source: string;
  license: string;
  kind: ModelKind;
  /** [w, d]: hex cells when footprintUnit is "hex", world units (metres) when "m". */
  footprint: [number, number];
  footprintUnit: "hex" | "m";
  /** Height in world units after `scale`. */
  height: number;
  /** Uniform scale that brings the model to the world unit. */
  scale: number;
  /** Bounding box size [x, y, z] in world units after `scale`. */
  size: [number, number, number];
  /** Lowest point in world units after `scale` (tiles sit with their top at y=0, so theirs is -1). */
  minY: number;
  tags: string[];
  /** Characters only: the clip names embedded in the glb. */
  animations?: string[];
  /** Blocks walking. */
  solid: boolean;
  /** Not part of the first load. */
  lazy: boolean;
  bytes: number;
  walkable?: boolean;
  overlay?: boolean;
  /** Slope tiles: how far the top rises across the tile. */
  rise?: number;
  /** Node names removed from the source model (weapons, hats). */
  stripped?: string[];
  notes?: string;
  banned: boolean;
  reason: string;
}

export interface ModelManifest {
  version: 1;
  unit: "metre";
  worldUnit: string;
  /** KayKit hex tile width across the flats (X axis); tiles are pointy-top. */
  hexSize: number;
  hexCornerToCorner: number;
  hexEdge: number;
  tileThickness: number;
  levelHeight: number;
  characterHeight: number;
  licenses: Record<string, string>;
  firstLoadBytes: number;
  totalBytes: number;
  models: Record<string, ModelEntry>;
}

export function isModelKind(value: unknown): value is ModelKind {
  return (
    typeof value === "string" &&
    (MODEL_KINDS as readonly string[]).includes(value)
  );
}

/** Model names the engine may load (banned ones are refused). */
export function usableModels(manifest: ModelManifest): string[] {
  return Object.entries(manifest.models)
    .filter(([, m]) => !m.banned)
    .map(([name]) => name);
}
